// Strategy: thêm Apple Pay mà không sửa switch 200 dòng của Checkout.vue.
const processors: Record<PaymentKind, PayFn> = {
  card: payWithCard,
  paypal: payWithPaypal,
  apple: payWithApple, // kind mới = hàm mới, không phải nhánh mới trong SFC
}
export async function pay(kind: PaymentKind, input: PayInput) {
  const fn = processors[kind]
  if (!fn) throw new Error(`unsupported payment ${kind}`)
  return fn(input)
}
// Adapter: Checkout nói với PaymentGateway, không bao giờ với type Stripe.js.
export const stripeGateway: PaymentGateway = {
  charge: (cents) => stripe.paymentIntents.create({ amount: cents, currency: "usd" }),
}

